import "fmt"

func main() {
	var a, b int
	fmt.Scan(&a, &b)

	c1, c2, c3 := 0, 0, 0

	for i := 6; i > 0; i-- {
		x := i - a
		if x < 0 {
			x = -x
		}
		y := i - b
		if y < 0 {
			y = -y
		}

		if x < y {
			c1++
		} else if x > y {
			c2++
		} else {
			c3++
		}
	}

	fmt.Println(c1, c3, c2)
}

